        atTicks(t + 20, "mana lleno (con la Mente 40)", m -> server(m, com.darkcraft.armas.Combos::llenar));
        atTicks(t + 36, "al empezar (la espada trae el torbellino)", m -> logHabilidad(m, "al empezar"));
