            if (e == null) return;
            e.moveTo(reino[0] + 0.5, CastlePlan.Y0, reino[1] + 66.5, 180f, 0f);
            verDesdeServidor = new Vec3(e.getX() - 2.8, e.getY() + 1.9, e.getZ() - 3.8);
