            a.setYRot(90f);
            a.yBodyRot = a.yHeadRot = 90f;
            a.empezar(com.darkcraft.enemigos.CalcinadoAnims.AGARRON);
            verDesdeServidor = new Vec3(CX + 26.5, PISO + 1.9, CZ - 2.6);
            miraServidor = new Vec3(CX + 26.8, PISO + 1.0, CZ + 0.5);
